CREATE OR REPLACE VIEW Clnc_VProc AS
 SELECT
        C.Id         Cat_Id       ,
        C.Status_Id  Cat_Status_Id,
        C.Special_Id Cat_Special_Id,
        C.Name       Cat_Name     ,
        C.Rem        Cat_Rem      ,
        P.Id         Proc_Id      ,
        P.Vat_Id     Proc_Vat_Id  ,
        P.Code       Proc_Code    ,
        P.Name       Proc_Name    ,
        P.Price      Proc_Price   ,
        P.Vat        Proc_Vat
   FROM Clnc_Cat  C,
        Clnc_Proc P
  WHERE P.Cat_Id=C.Id;

